package com.astro.prediction;

import java.util.HashMap;
import java.util.Map;

/** Planet-in-sign interpretation texts (~40 words each). */
public final class PlanetSignTexts {
    private PlanetSignTexts() {}

    public static String get(String planet, String sign) {
        return DATA.getOrDefault(planet + "_" + sign,
            planet + " is placed in " + sign + ", expressing its energies through the qualities of this sign.");
    }

    private static final Map<String, String> DATA = new HashMap<>();
    static {
        // ── SUN ──────────────────────────────────────────────────────────────
        DATA.put("Sun_Aries",       "Exalted. Leadership, pioneering vitality, and entrepreneurial drive define your solar identity. You project confidence and command naturally, energized by challenge and competition. The pioneer archetype is your deepest solar expression — you are here to begin, inspire, and lead.");
        DATA.put("Sun_Taurus",      "Solar identity rooted in material security and sensory pleasure. You build selfhood through accumulation, quality, and the patient perfection of what you create and possess. Beauty, physical comfort, and the refinement of material life are genuine self-expressions, not mere indulgences.");
        DATA.put("Sun_Gemini",      "Intellectual vitality and communicative self-expression characterize your solar nature. You are most fully yourself when learning, explaining, or connecting diverse ideas across domains. Mental agility is your greatest solar gift — curiosity is your primary fuel, and the exchange of ideas is your life-blood.");
        DATA.put("Sun_Cancer",      "Emotional authority and protective leadership. Solar identity is inseparable from home, family, and ancestral roots. You lead through nurturing rather than force, drawing solar power from the strength of emotional bonds and the security of your inner sanctuary.");
        DATA.put("Sun_Leo",         "Own sign — maximum solar expression. Charisma, authority, and creative magnetism are your natural endowments. You inspire others through the warmth of your presence. Born to lead, create, and be witnessed, you require genuine recognition as vital nourishment.");
        DATA.put("Sun_Virgo",       "Analytical, service-oriented solar expression devoted to excellence and precise improvement. You identify through intelligence, skill mastery, and the steady refinement of systems and processes. The satisfaction of work done perfectly is your deepest solar fulfillment.");
        DATA.put("Sun_Libra",       "Debilitated — solar self-assertion is softened by Libra's relational orientation. Identity expresses through harmony, fairness, and aesthetic refinement. Supremely diplomatic, you must consciously cultivate decisive, self-directed authority as an ongoing developmental priority throughout life.");
        DATA.put("Sun_Scorpio",     "Deep, transformative solar force beneath a controlled exterior. You identify through psychological intensity, hidden truth investigation, and regenerative power. Magnetic authority operates quietly but profoundly — others sense your solar power before you choose to reveal it.");
        DATA.put("Sun_Sagittarius", "Philosophical, expansive, and freedom-loving solar expression. You identify as a seeker and teacher of truth, drawing energy from learning, travel, and the pursuit of higher meaning. Your genuine enthusiasm for wisdom-seeking is both your solar gift and your calling.");
        DATA.put("Sun_Capricorn",   "Disciplined, executive, achievement-oriented solar identity built through patient competence and the methodical construction of lasting structures. Career and social standing are deeply intertwined with your sense of self. Authority is earned, never assumed.");
        DATA.put("Sun_Aquarius",    "Humanitarian, progressive, intellectually independent solar expression. You identify with collective ideals and social vision over personal glory. Innovation, reform, and the championing of universal principles channel your solar energy toward contributions that outlast individual recognition.");
        DATA.put("Sun_Pisces",      "Compassionate, spiritual, boundary-dissolving solar expression. Identity merges with universal consciousness — you identify with the whole rather than the part. Artistic sensitivity, mystical depth, and profound empathy are your solar gifts, though clear personal identity requires conscious cultivation.");
        // ── MOON ─────────────────────────────────────────────────────────────
        DATA.put("Moon_Aries",      "Rapid, impulsive, and intensely independent emotional nature. Feelings arise and are expressed with direct spontaneous force. Emotional courage is extraordinary; emotional patience requires deliberate cultivation. You react instinctively and genuinely, needing freedom to act on feeling without delay.");
        DATA.put("Moon_Taurus",     "Exalted — maximum lunar expression. Steady, sensual, deeply grounded emotional nature capable of sustained nurturing. You create emotional security through physical comfort, beautiful environments, and reliable rhythms. Loyalty once given is absolute; attachment to comfort requires mindful attention.");
        DATA.put("Moon_Gemini",     "Dual, restless, intellectually active emotional nature. Feelings are processed through articulation — you understand what you feel most clearly when you can explain it. Emotional security comes through mental stimulation and conversational freedom. Emotional depth requires conscious cultivation.");
        DATA.put("Moon_Cancer",     "Own sign — the Moon flourishes in its own home with full nurturing power. Deeply intuitive, empathetic, home-loving, and emotionally intelligent. Memory is exceptional; bonds formed are intensely felt. The challenge is releasing the past and managing the tidal quality of your feeling-cycles.");
        DATA.put("Moon_Leo",        "Generous, dramatic, and warmly expressive emotional nature. You feel pride in caring for those you love and need appreciation in return. Emotionally courageous and creatively expressive, you brighten every environment through the sheer warmth of your presence.");
        DATA.put("Moon_Virgo",      "Analytical, discerning, and service-oriented emotional nature. Feelings are processed through analysis and expressed through acts of helpful attention to detail. Emotional well-being is tied to order, purpose, and the satisfaction of being genuinely useful. Self-criticism requires conscious management.");
        DATA.put("Moon_Libra",      "Harmonious, relationally-oriented, and aesthetically sensitive emotional nature. You feel most yourself in peaceful, beautiful environments and in the company of those you genuinely enjoy. Conflict disturbs your emotional equilibrium profoundly; the need for balance must not become avoidance of necessary truth.");
        DATA.put("Moon_Scorpio",    "Debilitated — emotional intensity is magnified and sometimes overwhelming. You feel deeply, love passionately, and experience emotional wounds at significant depth. Psychological perceptiveness is extraordinary. The challenge involves releasing rather than holding — releasing resentments, secrets, and the grip of intense experience.");
        DATA.put("Moon_Sagittarius", "Optimistic, philosophical, and freedom-loving emotional nature. You process feelings through humor, philosophical reflection, and the expansive perspective that comes from genuine wisdom. Emotional well-being requires freedom, travel, and the sense that life has inherent meaning and direction.");
        DATA.put("Moon_Capricorn",  "Emotionally reserved, disciplined, and quietly devoted. Feelings are deep but not easily displayed; you show care through reliability and practical support rather than emotional display. Emotional maturity develops powerfully over time as Saturn's patience transforms restriction into genuine wisdom.");
        DATA.put("Moon_Aquarius",   "Emotionally detached yet genuinely humanitarian. You care deeply about people as a collective while sometimes finding individual emotional intimacy less natural. Friends and intellectual community provide essential emotional nourishment. The challenge is warming your emotional expression without losing your distinctive cool.");
        DATA.put("Moon_Pisces",     "Deeply compassionate, empathic, and spiritually attuned emotional nature. You absorb and transmute the emotions around you with remarkable fluency. Psychic sensitivity is real; emotional boundaries require deliberate cultivation to prevent depletion. Artistic expression and spiritual practice are primary emotional health practices.");
        // ── MERCURY ──────────────────────────────────────────────────────────
        DATA.put("Mercury_Aries",   "Rapid, direct, and assertive mental style. Your thinking is quick, decisive, and often arrives at correct conclusions before slower reasoners have finished considering the question. The challenge is impatience with complexity and a tendency to conclude before all data is in.");
        DATA.put("Mercury_Taurus",  "Deliberate, thorough, and practically oriented mental style. You think carefully and reach conclusions slowly — but once reached, your positions are well-grounded and difficult to dislodge. Learning is sensory and experiential as much as conceptual.");
        DATA.put("Mercury_Gemini",  "Own sign — maximum Mercury expression. Exceptionally quick, versatile, multi-layered thinking with an extraordinary capacity for information processing across diverse domains simultaneously. Writing, teaching, and persuasion are natural gifts. Managing mental scatter requires deliberate focus practice.");
        DATA.put("Mercury_Cancer",  "Emotionally intuitive and deeply memory-oriented mental style. You think through feeling as much as through reason, and your intuitive sense of a situation is often more accurate than your purely logical assessment. Learning is enhanced when emotional engagement is present.");
        DATA.put("Mercury_Leo",     "Confident, expressive, and dramatically communicative mental style. You think in broad strokes and communicate with natural authority that commands attention. Storytelling, public speaking, and creative writing are natural domains. Resistance to criticism of your ideas requires conscious management.");
        DATA.put("Mercury_Virgo",   "Exalted — Mercury at maximum precision, analytical depth, and discriminating intelligence. Your mind is an extraordinary tool for detailed analysis, systematic problem-solving, and the identification of flaws that others miss entirely. The challenge is perfectionism and the inner critic's relentless voice.");
        DATA.put("Mercury_Libra",   "Balanced, diplomatic, and aesthetically refined mental style. You are gifted at seeing all sides of any question and articulating multiple perspectives with precision and fairness. Legal reasoning, mediation, and philosophical dialogue are natural intellectual environments.");
        DATA.put("Mercury_Scorpio", "Penetrating, psychologically astute, and investigative mental style. Your thinking operates beneath the obvious surface, probing for hidden causes, unexpressed motivations, and the structural truths beneath appearances. Research, psychology, and strategic thinking are natural domains.");
        DATA.put("Mercury_Sagittarius", "Philosophical, expansive, and principle-seeking mental style. You think in large patterns and are most interested in the big picture, the fundamental principle, and the higher meaning behind individual facts. Detail work requires conscious effort; synthesis is your natural gift.");
        DATA.put("Mercury_Capricorn", "Strategic, disciplined, and practically intelligent mental style. Your thinking is methodical, goal-oriented, and reliably translated into effective action. You are most mentally engaged when solving real problems with tangible outcomes. Long-range planning is a natural cognitive strength.");
        DATA.put("Mercury_Aquarius", "Innovative, unconventional, and systems-level mental style. Your thinking naturally reaches beyond consensus toward original connections that others have not yet noticed. Technology, social systems, and future-oriented problem-solving engage your mind most powerfully.");
        DATA.put("Mercury_Pisces",  "Debilitated — Mercury's analytical precision is softened by Pisces' oceanic, boundary-dissolving quality. Your thinking is intuitive, associative, and imaginatively rich rather than strictly logical. You understand through feeling and metaphor as much as through analysis; creative and spiritual intelligence compensate for what sequential reasoning may miss.");
        // ── VENUS ────────────────────────────────────────────────────────────
        DATA.put("Venus_Aries",     "Venus in Aries brings passionate, immediate, and boldly expressive love and aesthetic instinct. You pursue beauty and connection with the same direct energy you bring to all things — impulsively, enthusiastically, and without reservation. Independence within relationship is essential to your heart's health.");
        DATA.put("Venus_Taurus",    "Own sign — Venus is most naturally itself in Taurus. Deep sensuality, profound aesthetic refinement, steadfast devotion, and an extraordinary capacity for sustained physical and emotional pleasure characterize your relationship with love and beauty. Loyalty is absolute; possessiveness requires conscious monitoring.");
        DATA.put("Venus_Gemini",    "Intellectually stimulated love and aesthetically diverse expression. You are attracted to wit, communicative spark, and mental playfulness. Variety and conversational intimacy are genuine romantic needs. Artistic interests are broad and eclectic; creative writing and verbal art forms are natural channels.");
        DATA.put("Venus_Cancer",    "Deeply nurturing, emotionally rich, and home-centered approach to love and beauty. You create beauty through the warmth of domestic environments and the care you invest in those closest to you. Emotional security is your primary romantic requirement.");
        DATA.put("Venus_Leo",       "Dramatic, generous, and gloriously expressive approach to love and aesthetics. You love with royal generosity and need a partner who appreciates and honors your depth of giving. Creative self-expression through art, performance, and romantic gesture is a core life pleasure.");
        DATA.put("Venus_Virgo",     "Debilitated — Venus's expansive, pleasure-oriented energy is constrained by Virgo's critical discernment. You express love through acts of service and practical devotion rather than romantic declarations. High standards for relationship quality require careful balance with accepting the beautiful imperfection of the beloved.");
        DATA.put("Venus_Libra",     "Own sign — Venus in its most naturally refined and relationally harmonious expression. You are gifted in the social arts, possess refined aesthetic taste, and bring a quality of gracious fairness to all your close connections. Partnership and beauty are equal life purposes.");
        DATA.put("Venus_Scorpio",   "Intensely passionate, deeply possessive, and transformatively powerful approach to love. You love at extraordinary depth and expect the same depth in return. Betrayal is profoundly damaging; complete trust opens the extraordinary dimension of loyal, transformative intimacy that is your genuine gift to a partner.");
        DATA.put("Venus_Sagittarius", "Freedom-loving, philosophically oriented, and adventurous approach to love and beauty. You need both partnership and personal liberty — a companion on the journey of discovery rather than an anchor to a single place. Cross-cultural connections and philosophical compatibility enrich relationships most.");
        DATA.put("Venus_Capricorn", "Disciplined, loyal, and practically devoted approach to love. You show affection through reliability, material provision, and the steady building of shared structure over time. You take commitments seriously and sustain them with remarkable patience. Traditional expressions of enduring love are your natural romantic language.");
        DATA.put("Venus_Aquarius",  "Intellectually free, socially conscious, and unconventionally expressive approach to love. You need a partner who is also a friend and intellectual equal. Friendship networks and shared ideals enrich intimate relationships. Aesthetic interests tend toward the avant-garde, innovative, and technologically sophisticated.");
        DATA.put("Venus_Pisces",    "Exalted — the most spiritually refined and devotionally selfless expression of love. You love with extraordinary compassion, empathy, and a willingness to sacrifice for the beloved. Creative and spiritual arts flourish in this placement. The challenge is discerning when devotion becomes enabling or when idealization obscures honest seeing.");
        // ── MARS ─────────────────────────────────────────────────────────────
        DATA.put("Mars_Aries",      "Own sign — Mars at full competitive, pioneering power. Boldness, physical vitality, decisive action, and the sheer pleasure of challenge characterize your drive. You are a natural leader under pressure, first to act and first to recover. Impulsiveness requires conscious tempering.");
        DATA.put("Mars_Taurus",     "Slow to ignite but formidable once committed. Your drive is patient, methodical, and oriented toward tangible material outcomes. You persist where others quit, building toward goals with a steady, irresistible momentum that eventually produces results others couldn't achieve with greater speed.");
        DATA.put("Mars_Gemini",     "Mentally energetic, verbally assertive, and multi-project-oriented drive. Your competitive instinct expresses through debate, quick-witted verbal sparring, and the aggressive pursuit of intellectual goals. Multiple simultaneous initiatives are natural; sustained single-focus requires deliberate effort.");
        DATA.put("Mars_Cancer",     "Debilitated — Mars's direct assertive energy is complicated by Cancer's emotional, protective orientation. Drive is expressed through emotional protection of loved ones. Anger goes underground and emerges as moodiness or passive aggression. Channeling assertive energy into protective, nurturing action produces your most effective outcomes.");
        DATA.put("Mars_Leo",        "Courageous, dramatically expressive, and creatively ambitious drive. You pursue your goals with flair and expect recognition for your efforts. Leadership under pressure is natural; competitive arena situations energize rather than intimidate you. Pride must not prevent acknowledging mistakes.");
        DATA.put("Mars_Virgo",      "Precise, detail-oriented, and systematically assertive drive. You pursue goals through methodical analysis and careful preparation, preferring competent execution over dramatic gesture. Work ethic is exceptional; perfectionism must not produce paralysis. Mastery of craft is your competitive edge.");
        DATA.put("Mars_Libra",      "Drive is expressed through partnership, negotiation, and the pursuit of just outcomes. You are most effectively assertive when operating with a co-creator beside you rather than alone. Competition is moderated by diplomacy; the challenge is acting decisively when situations demand clarity over consultation.");
        DATA.put("Mars_Scorpio",    "Own sign — Mars in its most psychologically powerful, strategically intense, and emotionally relentless expression. Your drive operates beneath the surface, pursuing objectives with extraordinary tenacity and patience. Regenerative capacity after setbacks is unmatched. The depth of your competitive resolve is both your superpower and your occasional burden.");
        DATA.put("Mars_Sagittarius", "Enthusiastic, philosophically motivated, and freedom-loving drive. You pursue goals with genuine optimism and moral conviction, fighting for principles as readily as for personal advancement. The archer's arrow rarely stays fixed to one target — sustained focus is the developmental edge.");
        DATA.put("Mars_Capricorn",  "Exalted — Mars channeled through Capricorn's patient, strategic, methodically ambitious lens. Your drive is among the most effectively and sustainably expressed in the zodiac: disciplined, goal-oriented, and ultimately irresistible through sheer determined competence. Achievement through earned mastery is your natural mode.");
        DATA.put("Mars_Aquarius",   "Intellectually driven, reformist, and collectively oriented assertive energy. You fight most effectively for ideas, systems reform, and social causes rather than purely personal advancement. Originality and independence in approach to challenges are your competitive signature.");
        DATA.put("Mars_Pisces",     "Drive expressed through spiritual aspiration, compassionate service, and creative imagination. Your assertive energy moves in currents rather than in direct lines, making you most effective in fluid, intuitive, or artistic domains. The challenge is maintaining enough groundedness to complete what imagination begins.");
        // ── JUPITER ──────────────────────────────────────────────────────────
        DATA.put("Jupiter_Aries",   "Philosophical fire and pioneering wisdom. You expand through bold new ideas, independent spiritual investigation, and the direct application of principle to action. Teaching by example and leading philosophical explorations into unexplored territory are natural expressions of this placement.");
        DATA.put("Jupiter_Taurus",  "Wisdom expressed through material abundance, sensory refinement, and practical generosity. You understand that material prosperity and spiritual wellbeing are not opposed. Excellent for wealth accumulation; philosophical interests run toward the concrete, the beautiful, and the practically useful.");
        DATA.put("Jupiter_Gemini",  "Debilitated — expansive Jupiter is scattered by Gemini's multiple simultaneous orientations. Wisdom is broad but risks becoming superficial; philosophical interests are eclectic and wide-ranging. The challenge is choosing depth over breadth. Teaching, writing, and the gathering of diverse knowledge remain genuine gifts.");
        DATA.put("Jupiter_Cancer",  "Exalted — Jupiter's wisdom finds its deepest and most generous expression through Cancer's nurturing, home-oriented, emotionally intelligent medium. Exceptional capacity for compassionate teaching, generous family provision, and creating environments of profound spiritual and material abundance for all in your care.");
        DATA.put("Jupiter_Leo",     "Magnanimous, dramatically generous, and creatively wise. You teach through inspiration and example, sharing wisdom with natural royal generosity. Leadership positions that allow philosophical breadth and creative expression of principle bring the deepest satisfaction. Children and creative projects prosper under this placement.");
        DATA.put("Jupiter_Virgo",   "Wisdom expressed through systematic analysis, service, and the precise improvement of practical matters. You are most philosophically engaged when understanding can be translated into tangible helpful application. Healing, nutrition, and the philosophy of productive work are natural wisdom domains.");
        DATA.put("Jupiter_Libra",   "Wisdom expressed through justice, fairness, beautiful relationship, and diplomatic principle. Exceptional legal mind; philosophical interests center on ethics, aesthetics, and the governance of just social order. Partners and advisors play key roles in how wisdom develops and is most usefully expressed.");
        DATA.put("Jupiter_Scorpio", "Deep, penetrating, and transformatively expansive wisdom. Philosophical interest in the hidden dimensions of existence — psychology, the occult, death and rebirth, and the mysteries of consciousness. Teaching capacity operates most powerfully in contexts of profound transformation and psychological depth.");
        DATA.put("Jupiter_Sagittarius", "Own sign — maximum Jupiterian expression of wisdom, generosity, and philosophical expansiveness. Natural teacher, philosopher, and guide whose genuine enthusiasm for truth-seeking is infectious. Travel, higher education, spiritual exploration, and the sharing of knowledge with wide audiences all flow naturally.");
        DATA.put("Jupiter_Capricorn", "Debilitated — Jupiter's free-flowing expansiveness is restricted by Capricorn's disciplined, cautious structure. Wisdom is practical, earned through experience, and expressed conservatively. Traditional forms of knowledge and institutional structures of wisdom transmission are honored. Material ambition may occasionally crowd out broader philosophical vision.");
        DATA.put("Jupiter_Aquarius", "Wisdom expressed through humanitarian vision, innovative social philosophy, and the championing of collective human advancement. You teach and think in systems terms, seeing how individual lives fit into the larger patterns of social evolution. Progressive, technologically literate, and genuinely egalitarian philosophical orientation.");
        DATA.put("Jupiter_Pisces",  "Own sign — Jupiter in its oceanic, spiritually receptive, compassionately wise expression. Extraordinary intuitive wisdom, spiritual depth, and capacity for transcendent understanding. Healing, artistic, and mystical gifts are pronounced. The challenge is discerning practical wisdom from wishful thinking in the depths of Piscean feeling.");
        // ── SATURN ───────────────────────────────────────────────────────────
        DATA.put("Saturn_Aries",    "Debilitated — Saturn's patient, methodical energy conflicts with Aries' impulsive, immediate drive. Discipline is learned through the hard experience of impulsive action's consequences. Career and ambition develop through a process of trial, failure, and the eventual mastery that comes only through patient earned expertise.");
        DATA.put("Saturn_Taurus",   "Patient, methodical, and sustainably wealth-building Saturn energy. Discipline applied to material accumulation produces remarkable long-term results. You build structures — financial, physical, professional — that endure far beyond your own direct involvement. Delayed gratification is both your challenge and your most reliable strategy.");
        DATA.put("Saturn_Gemini",   "Mental discipline and sustained intellectual mastery. You develop expertise through patient study rather than quick assimilation, building genuine deep knowledge rather than broad surface familiarity. Writing, teaching, and communicative disciplines deepen over time into genuine mastery through Saturnian patient investment.");
        DATA.put("Saturn_Cancer",   "Saturn restricts and disciplines emotional expression, creating a native who appears stoic even when feeling deeply. Emotional maturity comes through the long experience of being the dependable caregiver when others could not be depended upon. Profound emotional wisdom and family responsibility develop through sustained experience.");
        DATA.put("Saturn_Leo",      "Saturn disciplines the solar creativity and demands that authority be earned rather than assumed. Positions of leadership come after significant delays and tests of character. When eventually achieved, they are sustained through genuine competence rather than mere charisma or birthright.");
        DATA.put("Saturn_Virgo",    "Saturn's discipline in Virgo produces extraordinary professional excellence, meticulous analytical intelligence, and remarkable capacity for sustained productive work. Among the most professionally reliable and technically skilled of all placements. The inner critic must be managed so that perfectionism serves rather than paralyzes.");
        DATA.put("Saturn_Libra",    "Exalted — Saturn finds its most constructive expression in Libra's domain of just relationships and social order. Exceptional capacity for sustained fair-minded governance, legal reasoning, and the patient construction of equitable structures that serve the collective good. Partnership commitments are taken with absolute seriousness.");
        DATA.put("Saturn_Scorpio",  "Deep, karmic, and intensely transformative Saturn placement. You work through profound psychological material — power, control, death, inheritance — with the patient, relentless discipline that is Saturn's signature contribution. Psychological depth and genuine regenerative mastery develop through sustained confrontation with what is most difficult.");
        DATA.put("Saturn_Sagittarius", "Saturn disciplines philosophical enthusiasm and demands that wisdom be earned through direct experience rather than inherited dogma. You develop genuine philosophical authority over time — a teacher whose convictions have been tested by life and found durable. Spiritual commitment deepens through sustained practice rather than initial enthusiasm.");
        DATA.put("Saturn_Capricorn", "Own sign — Saturn in full authority, structure-building, and patient ambition. You are among the most reliably ambitious, methodically disciplined, and ultimately accomplished of any planetary placements. Career achievement through earned mastery is the primary life theme. Success comes unmistakably but characteristically later than peers.");
        DATA.put("Saturn_Aquarius", "Own sign — Saturn channeled through Aquarius' humanitarian, system-reforming lens produces a gifted social architect whose patient, strategic contributions reshape institutional structures for collective benefit. Intellectual independence combined with disciplined long-range thinking makes you an effective and lasting reformer.");
        DATA.put("Saturn_Pisces",   "Saturn disciplines the oceanic Piscean spiritual life, producing a serious spiritual practitioner whose commitment to inner development is patient, systematic, and ultimately deeply effective. The challenge is that Saturn's weight in Pisces' domain can produce periods of spiritual isolation, depression, or the sense of divine abandonment that precede the deepest openings.");
        // ── RAHU ─────────────────────────────────────────────────────────────
        DATA.put("Rahu_Aries",      "Intense karmic drive toward self-assertion, pioneering action, and independent identity. This life's growth edge involves developing genuine courage, decisive self-direction, and the willingness to be first. An insatiable appetite for new experience, leadership roles, and physical vitality characterizes the Rahu in Aries obsession.");
        DATA.put("Rahu_Taurus",     "Karmic drive toward material accumulation, sensory pleasure, and the development of stable, beautiful, secure existence. This lifetime is oriented toward building material and emotional foundations. Appetite for wealth, beauty, and physical comfort is intense — at its best it produces remarkable prosperity through persistent material intelligence.");
        DATA.put("Rahu_Gemini",     "Insatiable mental appetite for information, communication, and intellectual mastery. This life's growth edge involves developing genuine communicative expertise, adaptability, and the capacity to bridge diverse domains and communities of knowledge. Writing, media, and information technology are natural karmic domains.");
        DATA.put("Rahu_Cancer",     "Karmic drive toward emotional depth, nurturing mastery, and the creation of profound home and family experience. There is an intense, sometimes amplified relationship with the mother archetype. This life involves learning to both give and receive authentic nurturing without manipulation or excessive need.");
        DATA.put("Rahu_Leo",        "Intense karmic drive toward creative self-expression, visibility, and the development of genuine authority and personal magnetism. An insatiable appetite for recognition and creative achievement characterizes this placement. The growth edge involves developing authentic rather than performed leadership.");
        DATA.put("Rahu_Virgo",      "Karmic drive toward analytical mastery, health consciousness, and precise service orientation. This life involves developing genuine technical expertise and the capacity for sustained, detail-perfect productive work. An obsessive quality toward precision and health matters often leads to expertise in medicine, nutrition, or analytical fields.");
        DATA.put("Rahu_Libra",      "Intense karmic drive toward relational harmony, social refinement, and the development of aesthetic intelligence. This life is strongly oriented toward partnership, diplomacy, and the creation of beautiful just social environments. An insatiable appetite for the ideal relationship can sometimes produce disappointment with the imperfect actual.");
        DATA.put("Rahu_Scorpio",    "Deep, intense karmic drive toward transformation, psychological investigation, and the penetration of hidden power dynamics. This placement creates a compulsive fascination with the occult, death, sexuality, shared resources, and the hidden dimensions of human experience. Extraordinary psychological depth when consciously worked.");
        DATA.put("Rahu_Sagittarius", "Insatiable appetite for philosophical truth, foreign cultures, higher education, and the expansion of understood possibility. This life is strongly oriented toward seeking, teaching, and traveling — both literally and philosophically. The growth edge involves translating inspiration into sustained practical wisdom.");
        DATA.put("Rahu_Capricorn",  "Intense karmic drive toward professional achievement, social status, and the construction of lasting institutions. This life is powerfully career-oriented, and the appetite for professional recognition and material success is profound. The growth edge involves ensuring achievement serves genuine purpose rather than mere ambition.");
        DATA.put("Rahu_Aquarius",   "Karmic drive toward innovation, social reform, and the development of humanitarian vision. This life involves working toward collective advancement through unconventional, often technologically sophisticated means. An insatiable appetite for progress, freedom, and the disruption of outdated social structures.");
        DATA.put("Rahu_Pisces",     "Intense karmic drive toward spiritual dissolution, artistic creation, and the transcendence of ordinary material consciousness. This life involves deep engagement with the spiritual, the imaginative, and the compassionate dimensions of existence. The growth edge involves grounding transcendent vision in practical, embodied, present-moment reality.");
        // ── KETU ─────────────────────────────────────────────────────────────
        DATA.put("Ketu_Aries",      "Past-life mastery of self-assertion and independent pioneering; in this life, aggressive self-promotion feels spiritually hollow. The soul has already done the warrior journey. You are called beyond raw courage toward the wisdom that emerges when individual will surrenders to universal purpose.");
        DATA.put("Ketu_Taurus",     "Past-life mastery of material accumulation and sensory pleasure; in this life, attachment to wealth and physical comfort feels somehow incomplete despite outward abundance. The soul is being redirected from having toward being — from the possession of beauty toward the direct recognition of the beautiful.");
        DATA.put("Ketu_Gemini",     "Past-life mastery of communication, information gathering, and intellectual versatility. In this life, restless mental activity can feel unsatisfying — a kind of knowing-without-depth. The soul seeks integration: fewer things known more completely, thought that serves genuine wisdom rather than mere information accumulation.");
        DATA.put("Ketu_Cancer",     "Past-life deep immersion in emotional life, family bonds, and nurturing roles. In this life, an instinctive independence from family entanglement and a drawing away from purely emotional orientation. The soul is developing a wisdom that transcends personal feeling toward universal compassion.");
        DATA.put("Ketu_Leo",        "Past-life mastery of creative self-expression, leadership, and the experience of being seen and celebrated. In this life, the hunger for recognition feels spiritually shallow. The soul is learning to shine without needing the spotlight — to contribute genuinely without requiring acknowledgment.");
        DATA.put("Ketu_Virgo",      "Past-life mastery of analytical precision and devoted service. In this life, excessive critical attention to detail and compulsive helpfulness may arise unexpectedly. The soul is learning to balance discerning intelligence with the surrender and compassion that transforms skill into wisdom.");
        DATA.put("Ketu_Libra",      "Past-life deep experience of partnership, diplomacy, and the pursuit of relational harmony. In this life, the reliance on others for identity and the prioritizing of relationship over self may feel both familiar and ultimately insufficient. The soul is developing autonomous, self-directed integrity.");
        DATA.put("Ketu_Scorpio",    "Past-life mastery of transformative psychological investigation and deep power dynamics. In this life, the familiar territory of intensity, control, and occult investigation can feel compulsive rather than freely chosen. The soul is learning to work with power without being consumed by it — transformation through release rather than through force.");
        DATA.put("Ketu_Sagittarius", "Past-life mastery of philosophical seeking, religious devotion, and the pursuit of transcendent truth. In this life, formal religious structures and philosophical systems may feel inadequate to your direct experiential knowing. The soul is discovering truth not as doctrine but as lived, present, immediate recognition.");
        DATA.put("Ketu_Capricorn",  "Past-life mastery of institutional ambition, social status achievement, and the patient building of material structures. In this life, conventional career goals may feel hollow despite success. The soul is being redirected from building external legacy toward developing the inner wealth that transcends position and accomplishment.");
        DATA.put("Ketu_Aquarius",   "Past-life mastery of collective work, social reform, and humanitarian idealism. In this life, group dynamics and collective causes may feel draining rather than energizing despite evident social concern. The soul is learning to contribute from inner fullness rather than from ideological obligation.");
        DATA.put("Ketu_Pisces",     "Past-life deep immersion in spiritual surrender, compassionate service, and the dissolution of individual identity into the universal. In this life, boundaries between self and other may feel naturally thin. The soul is learning to maintain a clear, grounded individual identity while remaining open to the vast compassion that is its truest nature.");
    }
}
